WHO = {'column': [('quanor', 0), ('aprieleut', 0), ('undanor', 145502), ('einldlllhdu', 145502), ('zellnor', 145502), ('einsof', 145691), ('zeflfeben', 145945), ('psiloceyeben', 0)], 'tree': [('aprilllhdu', 0), ('mugeylsen', 145247), ('zefllnvi', 145438), ('zefllnvi', 0), ('zellhdu', 0), ('dukklllnvi', 0), ('dukklllnvi', 145945), ('aprilfools', 145945)], 'temple': [('aprilnor', 145247), ('mugeyeben', 0), ('mugepy', 148170), ('shalflllhdu', 149699), ('zeflben', 154350), ('aprilnor', 0), ('einldlllhdu', 154732), ('muut', 157351)], 'manor': [('zellgepy', 145247), ('dukklllnvi', 0), ('mugeyfools', 146133), ('einldlllhdu', 147786), ('zeaslsen', 0), ('mugeyfools', 0), ('einldlllhdu', 0), ('zellgepy', 156562)], 'bridge': [('psillnor', 147340), ('psillnor', 147914), ('aprilnor', 148106), ('aprilnor', 148234), ('alphafoldmicro', 148551), ('qum', 148869), ('mugeyehdu', 150016), ('zeflfeben', 150592)], 'tower': [('aprillnvi', 148042), ('einllmicr', 148425), ('muut', 150976), ('mugeyehdu', 152380), ('einllmicr', 0), ('zellanor', 157815), ('einldgepy', 157815), ('qullllicr', 157815)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW44(OracleReleaseRuntimeW42):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
